// Design Ref: §6.1 Error Handling — emergencyBrake는 monitor-alert 워크플로우가 설정한다.
// $getWorkflowStaticData('global')는 워크플로우마다 별도로 저장되어 다른 워크플로우가 쓴
// 값을 읽을 수 없다. 두 워크플로우가 같은 서버에서 실행된다는 전제로 공유 파일을 쓴다
// (YAGNI: 별도 DB 미도입, monitor-alert의 '긴급브레이크 ON' 노드가 같은 파일에 기록).
// PROJECT_ROOT 하위에 두는 이유: OS temp는 재부팅/정리 시 지워져 긴급브레이크가 조용히
// 풀릴 수 있다(SETUP.md 참조) — PROJECT_ROOT 미설정 시에만 temp로 폴백한다.
const fs = require('fs');
const path = require('path');
const os = require('os');

const sharedStatePath = path.join($env.PROJECT_ROOT || os.tmpdir(), '.n8n-shared-state.json');
let shared = {};
try {
  shared = JSON.parse(fs.readFileSync(sharedStatePath, 'utf8'));
} catch (e) {
  // 파일이 없으면 긴급브레이크 미설정 상태로 간주
}

return [{ json: { ...$input.first().json, emergencyBrake: shared.emergencyBrake === true } }];

// Design Ref: §4.1 daily-publish node 4 — 키워드 수집
// ponytail: 네이버 데이터랩 Open API는 카테고리별 트렌드 검색어만 제공하고
// 롱테일 키워드 자동완성은 공식 API가 없어 크롤링이 필요하다.
// 1차 구현은 운영자가 n8n Set 노드/Static Data에 미리 넣어둔 후보 목록에서
// 순차 선택하는 최소 버전으로 시작하고, 후보 소진 시 운영자가 보충한다.
// 업그레이드 경로: 네이버 자동완성 비공식 엔드포인트 크롤링 노드 추가.
const staticData = $getWorkflowStaticData('global');
const pool = staticData.keywordPool || [];
if (pool.length === 0) {
  throw new Error('keywordPool이 비었습니다. Static Data에 후보 키워드를 채워주세요.');
}
const keyword = pool.shift();
staticData.keywordPool = pool;
return [{ json: { keyword } }];

// Design Ref: §4.1 node 5 — Gemini 응답에서 제목/본문 텍스트 추출
const resp = $input.first().json;
const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!text) {
  throw new Error('Gemini 응답에서 본문을 추출하지 못했습니다: ' + JSON.stringify(resp).slice(0, 300));
}
const m = text.match(/\[제목\]\s*([\s\S]*?)\s*\[본문\]\s*([\s\S]*)/);
// Gemini가 형식 지시를 안 지켰을 때의 fallback: 키워드를 제목으로, 전체 텍스트를 본문으로 사용
const title = m ? m[1].trim() : $('키워드 수집').first().json.keyword;
const body = m ? m[2].trim() : text.trim();
return [{ json: { ...$('키워드 수집').first().json, title, body } }];

// Design Ref: §4.1 node 7 — 발행전 체크리스트
// Plan FR-05 + 2026-11 SEO 감사 반영: 최소 글자 수, 사진 개수, 타 사이트 문장 유사도, 키워드 반복 과다,
// 제목 품질, 질문형 소제목, 문단 길이(모바일 가독성) 검사
const prevItem = $('본문 추출').first().json;
const body = prevItem.body;
const title = prevItem.title;
const imageResp = $input.first().json;
const imagePart = imageResp?.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
const imageUrl = imagePart ? `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}` : null;

const MIN_LENGTH = 1000;
const MAX_KEYWORD_RATIO = 0.03; // 키워드가 본문 길이의 3% 넘으면 과다 반복으로 판정
const MAX_PARAGRAPH_LENGTH = 200; // 모바일 가독성: 한 문단이 너무 길면 Fail

const paragraphs = body.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);

const checks = {
  minLength: body.length >= MIN_LENGTH,
  hasImage: !!imageUrl,
  // ponytail: 타 사이트 문장 유사도 체크는 외부 표절 검사 API 연동이 필요 (예: Winston AI, 한국어 지원 확인됨).
  // 1차 구현은 스킵하고 항상 통과 처리 — 외부 API 계약 전까지는 수동 검수로 보완.
  similarityOk: true,
  keywordRepetitionOk: (() => {
    const kw = prevItem.keyword;
    const count = body.split(kw).length - 1;
    return (kw.length * count / body.length) <= MAX_KEYWORD_RATIO;
  })(),
  hasTitle: !!title && title.length >= 5 && title.length <= 40 && title !== prevItem.keyword,
  hasQuestionSubheading: /^#{1,3}\s*.*\?\s*$/m.test(body),
  paragraphLengthOk: paragraphs.every(p => p.length <= MAX_PARAGRAPH_LENGTH)
};

const passed = Object.values(checks).every(Boolean);

return [{
  json: {
    ...prevItem,
    imageUrl,
    checks,
    passed
  }
}];

// Design Ref: §4.1 node 8 — 제휴비중 게이트 (module-4)
// Plan FR-08: 로드맵 단계별 정보성/제휴성 비중(100/0 -> 80/20 -> 60~70/30~40)
// ponytail: 실제 쇼핑커넥트 링크 삽입은 아직 커넥트 미연동이라 범위 밖.
// 여기서는 isAffiliatePost 플래그만 결정해 Playwright 스크립트에 전달한다.
// 연동 후 업그레이드 경로: isAffiliatePost=true일 때 Playwright 스크립트가
// 셀러 제공 상품 이미지/링크를 본문에 삽입하도록 확장.
const staticData = $getWorkflowStaticData('global');

// 운영자가 게이트 통과 후 수동으로 전환하는 값 (Design §5.2 User Flow 참조)
if (!staticData.roadmapPhase) {
  staticData.roadmapPhase = '지수성장기';
}
const RATIO_BY_PHASE = {
  '준비기': 0,
  '지수성장기': 0,
  '최적화진입': 20,
  '운영': 35
};
const affiliateRatio = RATIO_BY_PHASE[staticData.roadmapPhase] ?? 0;
staticData.affiliateRatio = affiliateRatio;

const isAffiliatePost = Math.random() * 100 < affiliateRatio;

return [{
  json: {
    ...$input.first().json,
    roadmapPhase: staticData.roadmapPhase,
    affiliateRatio,
    isAffiliatePost
  }
}];

// Design Ref: §4.1 node 10 — 상태 기록, Plan FR-07 중복 발행 방지
const staticData = $getWorkflowStaticData('global');
staticData.lastPublishedDate = new Date().toISOString().slice(0, 10);
return $input.all();
